215	\section{Derivations and algorithms}
216	
217	\subsection{Blahut-Arimoto updates for the MI objective} \label{sec:ba_mi}
218	
219	As per \cite{mattingly2018}.
220	
221	\begin{eqnarray}
222	    p_{\tau+1}(\theta) = \frac{1}{Z_\tau} e^{\KL{p(X \mid \theta)}{p(X)}} p_\tau(\theta) \\
223	    Z_\tau = \sum_{\theta \in \Theta} e^{\KL{p(X \mid \theta)}{p(X)}} p_\tau(\theta)
224	\end{eqnarray}
225	
226	\subsection{Derivation of the dynamic objective function} \label{sec:dyn_obj}
227	
228	In the case of trying to choose an optimal $p^*(\theta)$ repeatedly, we would want to maximise the MI between all past and future observations simultaneously. However, as individual past observations are not retained, all information about those is in the posterior distribution $p(\theta_{old} \mid X_{old})$, where $X_{old} \in \mathcal{X}^m$, estimated from $m$ observations, with the likelihood function remaining the same. The resulting MI maximisation is illustrated in the above Venn-diagram, and 
229	
230	\begin{equation}
231	    p^*(\theta \mid n, p_{x \mid \theta}, X_{old}) = \argmax_{p(\theta)} \mathcal{L}_{dyn} = \argmax_{p(\theta)} I(\theta, \theta_{old}) + I(\theta, X \mid \theta_{old})
232	\end{equation}
233	
234	\subsubsection{Projecting the posterior into observation space}
235	
236	For this objective to be completely defined, we'd need $p(\theta, \theta_{old} \mid n, m)$ to be defined. We'd like to avoid giving such a definition for now, and sidestep the problem by introducing a variable for synthetic observations, and assume it to be connected to the latent via the same likelihood function we used so far:
237	
238	\begin{equation}
239	    \tilde{x} \sim p(\tilde{x}) = \sum_{\theta_{old} \in \Theta} p(\tilde{x} \mid \theta_{old}) p(\theta_{old} \mid X_{old})
240	\end{equation}
241	
242	Then we make the following equivocation in the objective function, making it completely defined, albeit not in a way that makes the balancing effect of $n$ and $m$ explicit, to which we will come back later:
243	
244	\begin{equation}
245	    \mathcal{L}_{dyn} = \argmax_{p(\theta)} I(\theta, \tilde{x}) + I(\theta, X \mid \tilde{x})
246	\end{equation}
247	
248	\subsubsection{The future term}
249	
250	The conditional term is slightly easier to handle, so let's look at that first:
251	
252	\begin{equation}
253	    I(\theta, X \mid \tilde{x}) = \sum_{\tilde{x} \in \mathcal{X}} p(\tilde{x}) \sum_{\theta \in \Theta} p(\theta \mid \tilde{x}) \sum_{X \in \mathcal{X}^n} p(X \mid \theta, \tilde{x}) \log \frac{p(X \mid \theta, \tilde{x})}{p(X \mid \tilde{x})}
254	\end{equation}
255	
256	Here we observe that $\theta$ is a Markov blanket between $X$ and $\tilde{x}$, thus $p(X \mid \theta, \tilde{x}) = p(X \mid \theta)$ and $p(X \mid \tilde{x}) = \sum_{\theta \in \Theta} p(X \mid \theta, \tilde{x}) p(\theta) = p(X)$.
257	
258	Then we expand the conditional: 
259	
260	\begin{equation}
261	    p(\theta \mid \tilde{x}) = \frac{p(\tilde{x} \mid \theta) p(\theta)}{\sum_{\theta \in \Theta} p(\tilde{x} \mid \theta) p(\theta)}
262	\end{equation}
263	
264	Then introduce the shorthand $p_{new}(\tilde{x}) = \sum_{\theta \in \Theta} p(\tilde{x} \mid \theta) p(\theta)$, so the conditional MI becomes:
265	
266	\begin{equation}
267	    I(\theta, X \mid \tilde{x}) = \sum_{\tilde{x} \in \mathcal{X}} p(\tilde{x}) \sum_{\theta \in \Theta} \frac{p(\tilde{x} \mid \theta)}{p_{new}(\tilde{x})} p(\theta) \sum_{X \in \mathcal{X}^n} p(X \mid \theta) \log \frac{p(X \mid \theta)}{p(X)}
268	\end{equation}
269	
270	\subsubsection{The sampling trick}
271	
272	At this point we'd like to reintroduce the consideration that $m$ (or at least the ratio between it and $n$) should play a role in how much information do we actually copy from the posterior into the new prior. We do this by taking $m$ samples from $p(\tilde{x})$, and calculate the expectation using those:
273	
274	\begin{equation}
275	    \tilde{x}_1 \ldots \tilde{x}_m \sim p(\tilde{x})
276	\end{equation}
277	
278	\begin{eqnarray}
279	    I(\theta, X \mid \tilde{x}) \approx \frac{1}{m}\sum_{s=1}^m \sum_{\theta \in \Theta} \frac{p(\tilde{x}_s \mid \theta)}{p_{new}(\tilde{x}_s)} p(\theta) \sum_{X \in \mathcal{X}^n} p(X \mid \theta) \log \frac{p(X \mid \theta)}{p(X)} = \\
280	    = \sum_{\theta \in \Theta} p(\theta) \left[ \frac{1}{m}\sum_{s=1}^m \frac{p(\tilde{x}_s \mid \theta)}{p_{new}(\tilde{x}_s)} \right]  \sum_{X \in \mathcal{X}^n} p(X \mid \theta) \log \frac{p(X \mid \theta)}{p(X)}
281	\end{eqnarray}
282	
283	This approximation can be done fully stochastically as stated here, or if we retained any real observations in episodic memory, we can use those as well.
284	
285	\subsubsection{The past term}
286	
287	In order to be able to use the same set of samples for approximation, we expand the non-conditional term in the less intuitive way:
288	
289	\begin{equation}
290	    I(\theta, \tilde{x}) =  \sum_{\tilde{x} \in \mathcal{X}} p(\tilde{x}) \sum_{\theta \in \Theta} p(\theta \mid \tilde{x}) \log \frac{p(\theta \mid \tilde{x})}{p(\theta)} = 
291	    \sum_{\tilde{x} \in \mathcal{X}} p(\tilde{x}) \sum_{\theta \in \Theta} \frac{p(\tilde{x} \mid \theta) p(\theta)}{p_{new}(\tilde{x})} \log \frac{p(\tilde{x} \mid \theta)}{p_{new}(\tilde{x})}
292	\end{equation}
293	
294	
295	Then using the samples this becomes:
296	
297	\begin{equation}
298	    I(\theta, \tilde{x}) \approx  \sum_{\theta \in \Theta} p(\theta) \frac{1}{m}\sum_{s=1}^m \frac{p(\tilde{x}_s \mid \theta)}{p_{new}(\tilde{x}_s)}  \log \frac{p(\tilde{x}_s \mid \theta)}{p_{new}(\tilde{x}_s)}
299	\end{equation}
300	
301	\subsubsection{The full objective}
302	
303	From all the above it seems the full objective would be:
304	
305	\begin{equation}
